using System.Windows;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class ReplicaWindow:Window{public ReplicaWindow(){InitializeComponent();Loaded+=async(_,_)=>{if(DataContext is ReplicaViewModel vm)await vm.LoadAsync();};}async void Add_Click(object s,RoutedEventArgs e){if(DataContext is ReplicaViewModel vm)await vm.AddTargetAsync();}async void Links_Click(object s,RoutedEventArgs e){if(DataContext is ReplicaViewModel vm)await vm.SaveLinksAsync();}async void Folder_Click(object s,RoutedEventArgs e){if(DataContext is ReplicaViewModel vm)await vm.SaveFolderAsync();}}